import { spawnSync } from "node:child_process";
import { existsSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const localBin = path.join(root, "node_modules", "esbuild", "bin", "esbuild");
const args = [
  path.join(root, "scripts/community-api-entry.ts"),
  "--bundle",
  "--platform=node",
  "--format=esm",
  `--outfile=${path.join(root, "api/community-handler.js")}`,
  "--banner:js=// Generated by scripts/bundle-community-api.mjs. Do not edit.",
  "--external:@clerk/backend",
  "--external:@vercel/blob",
  "--external:@vercel/blob/client",
];

const command = existsSync(localBin) ? localBin : "npx";
const commandArgs = existsSync(localBin) ? args : ["--yes", "esbuild@0.28.2", ...args];
const result = spawnSync(command, commandArgs, { stdio: "inherit", cwd: root });
if (result.status !== 0) process.exit(result.status ?? 1);
